// The sound library shared by any episode: music beds, effects, ambience and
// the announcer, generated by tools/audio.mjs into audio/ next to this file.
// In the module build these are paths relative to index.html at the project
// root; the bundler swaps the episode's audio-manifest.js (which merges this
// with the episode's own voice clips) for one holding base64 data URIs.

export const LIBRARY_NAMES = [
  // music beds, looped
  'mus-theme', 'mus-romance', 'mus-suspense', 'mus-storm', 'mus-tragedy', 'mus-credits',
  // one-shots
  'sfx-crow', 'sfx-cluck', 'sfx-squawk', 'sfx-flap', 'sfx-thunder', 'sfx-slap',
  'sfx-egg-crack', 'sfx-peep', 'sfx-heartbeat', 'sfx-sting', 'sfx-sting-reveal',
  'sfx-gate-creak', 'sfx-cloth-whip', 'sfx-hen-gasp', 'sfx-footsteps-mud', 'sfx-organ-hold',
  // ambience, looped
  'sfx-rain', 'sfx-fountain', 'sfx-night',
  // the announcer
  'vo-title', 'vo-capitulo', 'vo-continuara',
  // the opening titles, one name at a time
  'vo-name-rosalinda', 'vo-name-esteban', 'vo-name-valentina',
  'vo-name-dongallo', 'vo-name-ricardo',
  'vo-credits-1', 'vo-credits-2', 'vo-credits-3', 'vo-credits-4', 'vo-credits-5',
];

export const LIBRARY = Object.fromEntries(LIBRARY_NAMES.map((n) => [n, `./company/library/audio/${n}.mp3`]));
